#!/usr/bin/env python3
"""TRUSTED emitter for ai4bio-cofolding-affinity-scoring -- do not edit.

Runs as the trusted uid AFTER the untrusted scoring phase has exited and its uid has been
killed off, so nothing of the agent's code is alive when this reads the archive. It
validates the raw predictions, re-writes them under a nonce IT generates (a nonce the
untrusted phase could otherwise forge), and prints the one authoritative marker.
"""
import argparse
import hashlib
import json
import os
import secrets
import sys
from pathlib import Path

import numpy as np

# The ligand keys this setting must score, sealed beside this file. It is the authority on
# WHICH keys are present: the fixture listing in the workspace and anything the editable
# module can reach (it ran in the untrusted phase) are not. Pinned by digest here, and this
# file is itself digest-checked by _run_driver.sh before it runs.
KEYS_FILE = Path(__file__).resolve().with_name("fixture_keys.json")
KEYS_SHA256 = "baa175e7afe5d1c9c203fe3ee0f9e013596920548c13ab9482c0634aef53e80b"


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--raw", required=True)
    ap.add_argument("--out", required=True)
    ap.add_argument("--env", required=True)
    ap.add_argument("--seed", required=True)
    ap.add_argument("--expect", type=int, default=0, help="ligands the fixture holds")
    a = ap.parse_args()

    def fail(rc: int, msg: str) -> int:
        print(f"\nFINAL_AFFINITY env={a.env} seed={a.seed} status=INVALID rc={rc}", flush=True)
        print(msg, file=sys.stderr, flush=True)
        return rc

    raw = Path(a.raw)
    if not raw.is_file():
        return fail(8, f"the scoring phase produced no archive at {raw}")
    try:
        with np.load(raw, allow_pickle=False) as z:
            keys = [str(k) for k in z["key"]]
            aff = np.asarray(z["affinity"], dtype=np.float64)
            prob = np.asarray(z["binder_prob"], dtype=np.float64)
            setting = str(z["setting"][0])
    except Exception as exc:                                       # noqa: BLE001
        return fail(8, f"unreadable archive {raw}: {exc}")
    if setting != a.env:
        return fail(8, f"archive was produced for {setting!r}, not {a.env!r}")
    if not (len(keys) == len(aff) == len(prob)) or not keys:
        return fail(8, "archive arrays disagree in length")
    if len(set(keys)) != len(keys):
        return fail(8, "archive repeats a ligand key")
    try:
        blob = KEYS_FILE.read_bytes()
    except OSError as exc:
        return fail(9, f"sealed key list unreadable: {exc}")
    if hashlib.sha256(blob).hexdigest() != KEYS_SHA256:
        return fail(9, "sealed key list does not match its pinned digest")
    want = set(json.loads(blob).get(a.env, []))
    got = set(keys)
    if not want or got != want:
        return fail(8, f"archive key set differs from the sealed fixture list "
                       f"({len(want - got)} missing, {len(got - want)} unknown)")
    if a.expect and len(keys) != a.expect:
        return fail(8, f"archive holds {len(keys)} ligands, the fixture has {a.expect}")
    if not (np.isfinite(aff).all() and np.isfinite(prob).all()):
        return fail(8, "archive contains NaN or inf")

    nonce = secrets.token_hex(8)
    out = Path(a.out)
    out.parent.mkdir(parents=True, exist_ok=True)
    np.savez_compressed(out, key=np.array(keys), affinity=aff, binder_prob=prob,
                        nonce=np.array([nonce]), setting=np.array([a.env]))
    try:
        os.chmod(out, 0o444)
    except OSError:
        pass
    line = (f"FINAL_AFFINITY env={a.env} seed={a.seed} status=OK "
            f"nonce={nonce} path={out}")
    print("\n" + line, flush=True)
    rf = os.environ.get("MLSBENCH_RESULT_FILE")
    if rf:
        with open(rf, "a") as fh:
            fh.write(line + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())

