"""Host-side scorer for ai4bio-cofolding-affinity-scoring (A-pattern).

Runs in the harness process (native) or the Harbor verifier's sealed meta copy -- never
inside the agent container. The fixed driver writes one npz of predictions to OUTPUT_DIR and
prints a nonce-gated FINAL_AFFINITY marker naming it. The experimental affinities live in
`dgp` and are unreachable from the workspace, so forging the marker buys nothing: every
metric is computed HERE against labels the container never saw.
"""
from __future__ import annotations

import json
import re
import sys
from pathlib import Path

import numpy as np

_HERE = Path(__file__).resolve().parent
_ROOT = _HERE.parents[1]

try:
    from mlsbench.agent.parsers import OutputParser, ParseResult
except ModuleNotFoundError:            # native checkout without an install
    sys.path.insert(0, str(_ROOT / "src"))
    from mlsbench.agent.parsers import OutputParser, ParseResult
from mlsbench.holdout import load_holdout_module  # noqa: E402

dgp = load_holdout_module("ai4bio-cofolding-affinity-scoring", __file__)

_CFG = Path(__file__).with_name("config.json")
_SEEDS = (set(int(s) for s in json.loads(_CFG.read_text()).get("seeds", [42]))
          if _CFG.exists() else {42})
# NOT anchored at ^: a progress line can leave the cursor mid-line, and an anchored pattern
# then silently sees no marker and a SUCCESSFUL run scores nothing.
_MARKER = re.compile(
    r"FINAL_AFFINITY env=(?P<env>\S+) seed=(?P<seed>\d+) "
    r"(?:status=OK nonce=(?P<nonce>[0-9a-f]+) path=(?P<path>\S+)"
    r"|status=INVALID rc=(?P<rc>-?\d+))")


def _refuse(msg: str, raw: str) -> ParseResult:
    """No metric at all. A run that did not complete must not yield a number."""
    print(f"[parser] REFUSED ({msg})", file=sys.stderr, flush=True)
    print(f"[parser] REFUSED ({msg})", flush=True)
    return ParseResult(feedback=msg + "\n" + "\n".join(raw.splitlines()[-25:]), metrics={})


class Parser(OutputParser):
    def parse(self, cmd_label: str, raw_output: str) -> ParseResult:
        match = None
        for m in _MARKER.finditer(raw_output):
            if m.group("env") == cmd_label:
                match = m
        if match is None:
            return _refuse(f"{cmd_label}: no FINAL_AFFINITY marker (the fixed driver emits "
                           f"it).", raw_output)
        if match.group("rc") is not None:
            return _refuse(f"{cmd_label}: the driver did not complete "
                           f"(rc={match.group('rc')}).", raw_output)
        if int(match.group("seed")) not in _SEEDS:
            return _refuse(f"{cmd_label}: seed {match.group('seed')} is not a task seed.",
                           raw_output)
        path = Path(match.group("path"))
        if not path.exists():
            return _refuse(f"{cmd_label}: prediction archive {path} is missing.", raw_output)
        try:
            with np.load(path, allow_pickle=False) as z:
                if str(z["nonce"][0]) != match.group("nonce"):
                    return _refuse(f"{cmd_label}: archive carries a stale run token.", raw_output)
                if str(z["setting"][0]) != cmd_label:
                    return _refuse(f"{cmd_label}: archive was produced for another setting.",
                                   raw_output)
                keys = [str(k) for k in z["key"]]
                aff = {k: float(v) for k, v in zip(keys, z["affinity"])}
                prob = {k: float(v) for k, v in zip(keys, z["binder_prob"])}
        except Exception as exc:                                  # noqa: BLE001
            return _refuse(f"{cmd_label}: could not read the archive ({exc}).", raw_output)

        res = dgp.score_predictions(cmd_label, aff, prob)
        if res["n_groups"] == 0:
            why = res.get("refused") or "no group could be scored"
            return _refuse(f"{cmd_label}: {why} ({res['n_keys']} labelled keys expected; "
                           f"the driver returned {len(aff)}).", raw_output)

        # AGGREGATE ONLY. Per-series lines would hand the agent a per-token score to tune
        # against (and did); the per-group table stays in dgp's return value for the host.
        if cmd_label == "leadopt":
            metrics = {f"pearson_{cmd_label}": res["pearson"],
                       f"spearman_{cmd_label}": res["spearman"],
                       f"mue_{cmd_label}": res["mue"]}
            head = (f"{cmd_label}: {res['n_groups']} series scored; mean Pearson "
                    f"{res['pearson']:+.3f}, Spearman {res['spearman']:+.3f}, "
                    f"MUE {res['mue']:.2f} kcal/mol")
        else:
            metrics = {f"auroc_{cmd_label}": res["auroc"],
                       f"ap_{cmd_label}": res["ap"],
                       f"ef5_{cmd_label}": res["ef5"]}
            head = (f"{cmd_label}: {res['n_groups']} targets scored; mean AUROC "
                    f"{res['auroc']:.3f}, AP {res['ap']:.3f}, EF5% {res['ef5']:.2f}")
        print("[parser] " + head, flush=True)
        return ParseResult(feedback=head, metrics=metrics)

